package dns
import("fmt";"net";"sort";"strings")
type SPFRecord struct{Domain string `json:"domain"`;Mechanisms []string `json:"mechanisms,omitempty"`;IP4 []string `json:"ip4,omitempty"`;IP6 []string `json:"ip6,omitempty"`;Include []string `json:"include,omitempty"`;All string `json:"all"`}
func(r SPFRecord)Validate()error{domain:=strings.TrimSuffix(strings.ToLower(strings.TrimSpace(r.Domain)),".");if domain==""||len(domain)>253||strings.ContainsAny(domain," \t\r\n/"){return fmt.Errorf("invalid domain")};all:=strings.ToLower(strings.TrimSpace(r.All));if all!=""&&all!="pass"&&all!="fail"&&all!="softfail"&&all!="neutral"{return fmt.Errorf("invalid all qualifier")};if len(r.Mechanisms)>64||len(r.Include)>64{return fmt.Errorf("too many SPF mechanisms")};for _,m:=range r.Mechanisms{m=strings.TrimSpace(m);if m==""||len(m)>256||strings.ContainsAny(m,"\r\n\x00"){return fmt.Errorf("invalid SPF mechanism")}};nets:=append(append([]string{},r.IP4...),r.IP6...);if len(nets)>100{return fmt.Errorf("too many networks")};for _,cidr:=range nets{cidr=strings.TrimSpace(cidr);if _,_,err:=net.ParseCIDR(cidr);err!=nil{return fmt.Errorf("invalid network: %s",cidr)}};for _,inc:=range r.Include{inc=strings.TrimSpace(inc);if inc==""||len(inc)>253||strings.ContainsAny(inc," \t\r\n/"){return fmt.Errorf("invalid SPF include")}};return nil}
func(r SPFRecord)TXTValue()(string,error){if err:=r.Validate();err!=nil{return "",err};parts:=[]string{"v=spf1"};for _,v:=range r.Mechanisms{v=strings.TrimSpace(v);if v!=""{parts=append(parts,v)}};for _,ip:=range r.IP4{ip=strings.TrimSpace(ip);if ip!=""{parts=append(parts,"ip4:"+ip)}};for _,ip:=range r.IP6{ip=strings.TrimSpace(ip);if ip!=""{parts=append(parts,"ip6:"+ip)}};includes:=append([]string(nil),r.Include...);sort.Strings(includes);for _,inc:=range includes{inc=strings.TrimSpace(inc);if inc!=""{parts=append(parts,"include:"+inc)}};if q:=r.AllQualifier();q!=""{parts=append(parts,q)};return strings.Join(parts," "),nil}
func(r SPFRecord)AllQualifier()string{switch strings.ToLower(strings.TrimSpace(r.All)){case "pass":return "+all";case "fail":return "-all";case "softfail":return "~all";case "neutral":return "?all";default:return ""}}
